"""Seeded package comparison on the synthetic curves generated by fits.py."""
from contextlib import redirect_stdout
import csv
from io import StringIO
import sys

import MulensModel as mm
import numpy as np
from pyLIMA import event, telescopes
from pyLIMA.fits.TRF_fit import TRFfit
from pyLIMA.models.FSPLarge_model import FSPLargemodel
from pyLIMA.models.PSPL_model import PSPLmodel
from singlelensfitter import FSPLFitter, PSPLFitter

from fits import fd_fit, measure, synthetic_event


def run(finite, a):
    time, flux, error, seed, vbm = synthetic_event(finite, a)
    slf = FSPLFitter(linear_limb_darkening=a) if finite else PSPLFitter()
    telescope = telescopes.Telescope(
        name="survey", lightcurve=np.column_stack((time, flux, error)),
        lightcurve_names=["time", "flux", "err_flux"],
        lightcurve_units=["JD", "W/m^2", "W/m^2"])
    for name, expected in zip(("time", "flux", "err_flux"), (time, flux, error)):
        np.testing.assert_array_equal(telescope.lightcurve[name].value, expected)
    telescope.ld_a1 = a
    data = event.Event()
    data.telescopes.append(telescope)
    trf = TRFfit(FSPLargemodel(data) if finite else PSPLmodel(data))
    if finite:
        trf.fit_parameters["rho"][1] = (5e-5, 1.)  # Include the injected radius 0.24.

    params = dict(t_0=seed[0], t_E=seed[1], u_0=seed[2])
    if finite:
        params["rho"] = np.exp(seed[3])
    model = mm.Model(params)
    if finite:
        model.default_magnification_method = ("finite_source_LD_Yoo04" if a
                                              else "finite_source_uniform_Gould94")

    def mm_curve(q):
        model.parameters.t_0, model.parameters.t_E, model.parameters.u_0 = q[:3]
        if finite:
            model.parameters.rho = np.exp(q[3])
        return model.get_magnification(time, gamma=2*a/(3-a))

    def pylima_fit():
        trf.model_parameters_guess = [seed[0], seed[2], seed[1]]
        if finite:
            trf.model_parameters_guess.append(np.exp(seed[3]))
        trf.telescopes_fluxes_parameters_guess = []
        trf.fit_results = {}
        with redirect_stdout(StringIO()) as log:
            trf.fit()
        result = trf.fit_results
        if not result or not result["fit_object"].success:
            raise RuntimeError(f"pyLIMA TRF fit failed: {log.getvalue()} {trf.fit_parameters}")
        return float(result["chi2"])

    def slf_fit():
        r = slf.fit(time, flux, error, seed)
        if not r.optimizer_success:
            raise RuntimeError(r.optimizer_status)
        return float(r.chi2)

    return measure({"SLF seeded": slf_fit, "VBM + FD": lambda: fd_fit(vbm, flux, error, seed),
                    "MulensModel + FD": lambda: fd_fit(mm_curve, flux, error, seed),
                    "pyLIMA TRFfit": pylima_fit})


if __name__ == "__main__":
    import multiprocessing
    multiprocessing.set_start_method("spawn")
    writer = csv.writer(sys.stdout, lineterminator="\n")
    writer.writerow(["model", "method", "repeat", "ms", "chi2"])
    for label, finite, a in [("PSPL", False, 0.), ("Uniform FSPL", True, 0.),
                             ("Linear FSPL", True, .5)]:
        for method, rows in run(finite, a).items():
            for i, (ms, chi) in enumerate(rows, 1):
                writer.writerow([label, method, i, ms, chi])
